        require(sp.Poly(vvm_ser, th_s).coeff_monomial(th_s**4) == sp.Rational(-1, 2880), "VVM order 4")
        require(sp.Poly(haar_ser, r_s).coeff_monomial(r_s**6) == sp.Rational(1, 90720), "Haar order 6")

        PAIRS_G = [(m, n) for m in range(4) for n in range(m, 4)]; P2IDX_G = {pr: i for i, pr in enumerate(PAIRS_G)}
        WEDGE_PAIRS = [(a, b) for a in range(4) for b in range(a+1, 4)]
        def g_idx_s(i, j): return P2IDX_G[(i, j) if i <= j else (j, i)]
        def extract_Q_gram(poly4):
            Q = [[Fraction(0)]*10 for _ in range(10)]
            for I, (i, j) in enumerate(PAIRS_G):
                for J, (k, l) in enumerate(PAIRS_G):
                    e = [0]*12; e[3*i]+=1; e[3*j]+=1; e[3*k+1]+=1; e[3*l+1]+=1; Q[I][J] = poly4.get(tuple(e), Fraction(0))/2
            return Q
        Qw = extract_Q_gram(Sw4); Qm = extract_Q_gram(Sm4)
