        def iv_sinh(x): return (iv.exp(x) - iv.exp(-x)) / 2
        def iv_cosh(x): return (iv.exp(x) + iv.exp(-x)) / 2
        def haar_4plus_coeff_iv(rm):
            r = iv.mpf(rm.b)
            if mp.mpf(r.a) <= 0: return iv.mpf(1)/1440
            return (-2*iv.log(iv.sin(r/2)/(r/2)) - (r**2)/12)/(r**4)
        def haar_r4_plus_iv(r_iv): return (iv.mpf(2)/3)*((r_iv**4)/1440 + (r_iv**6)/90720 + (r_iv**8)/4000000)
        def haar_grad_r3_plus_iv(r_iv): return (iv.mpf(2)/3)*(4*(r_iv**3)/1440 + 6*(r_iv**5)/90720 + 8*(r_iv**7)/4000000)
        def manton_rem6_iv(rc_iv):
            sh = iv_sinh(rc_iv); X = 2*sh*sh; s_hi = (X + X*X/6) - (2*(rc_iv**2) + iv.mpf(4)/3*(rc_iv**4))
            c_n = iv.mpf(2)/45; Xn = X**3; s_term = c_n*Xn
            for n in range(4, 25): c_n = c_n*iv.mpf((n-1)**2)/iv.mpf(n*(2*n-1)); Xn *= X; s_term += c_n*Xn
            return s_hi + s_term + c_n*Xn*(X/2)/(1 - X/2)
        def manton_grad_rem5_iv(rc_iv):
            sh = iv_sinh(rc_iv); ch = iv_cosh(rc_iv); asin_sh = iv.mpf(0); coef = iv.mpf(1); shp = sh; sh2 = sh*sh
            for k in range(25):
                if k > 0: coef = coef*iv.mpf((2*k-1)*(2*k))/iv.mpf(4*k*k); shp *= sh2
                asin_sh += (coef/(2*k+1))*shp
            return 4*(asin_sh + (coef*shp*sh2/51)/(1-sh2))*ch/iv.sqrt(1-sh2) - (4*rc_iv + iv.mpf(16)/3*(rc_iv**3))
        def iv_gamma_q_int(m_int, x_iv):
            s = iv.mpf(0); term = iv.mpf(1)
            for k in range(m_int):
                if k > 0: term = term * x_iv / k
                s = s + term
            return iv.exp(-x_iv) * s

        c_sm4_sup_iv = (2 + iv.sqrt(13))/16; gtot_sm4_iv = iv.mpf("1.66759373124871154871778016")
        op_l1_w4 = iv.mpf("2.304890627282476106397405") * iv.mpf("1.005")
        lam_c4e_w4 = iv.mpf("0.6275945788049355619066274") * iv.mpf("1.005")
        diag_safe_w4 = iv.mpf("0.5431424882325468903969849") * iv.mpf("1.005")
        cB_w4 = iv.mpf("1.434872756241108924751287")
        c_wick_m1_w4 = c_sm4_sup_iv * 60 * (diag_safe_w4 ** 2)
        def eval_w11_manton(beta_int, s_soft_str, deg_adm_str, kz_str, mode):
            b = iv.mpf(beta_int); s_soft = iv.mpf(s_soft_str); s_eff = s_soft + iv.mpf(1)/(6*b); hr = s_eff/s_soft
            e_adm = 1 - iv.cos(iv.mpf(deg_adm_str)*iv.pi/360)
            u_st = (2 * b * e_adm) / (9 * cB_w4)
            if mp.mpf(u_st.a) <= 1: return iv.mpf("1e9")
            n_lf_st = 7*iv.e*(u_st**iv.mpf("4.5"))*iv.exp(iv.mpf("4.5")*(1-u_st))
            kz = iv.mpf(kz_str); rw = kz/iv.sqrt(b*s_soft)
            n_lf = n_lf_st + 21*iv_gamma_q_int(6, (4*(kz**2)*hr)/(2*lam_c4e_w4))
            if mp.mpf(n_lf.a) >= mp.mpf("0.35"): return iv.mpf("1e9")
            c_sw3_sup = iv.mpf(2)/(3*iv.sqrt(3)); gtot_3 = iv.mpf(2)/iv.sqrt(3); g1_3 = (3*iv.sqrt(3))/16; hop_3 = iv.mpf("0.75")
            eta_4 = b*(c_sm4_sup_iv*(rw**4)+manton_rem6_iv(rw))+haar_r4_plus_iv(rw)
            g_lf = b*(gtot_sm4_iv*(rw**3)+manton_grad_rem5_iv(rw))+haar_grad_r3_plus_iv(rw)
            m1_sf = 21*((c_wick_m1_w4/(b*(s_eff**2)))+b*manton_rem6_iv(rw)+haar_r4_plus_iv(rw))*iv.exp(eta_4)
            if mode == "k4_ibp_with_v3":
                norm_A = 2*op_l1_w4*hop_3*rw/s_eff
                if mp.mpf(norm_A.b) >= mp.mpf("0.85"): return iv.mpf("1e9")
                eta_p = iv.mpf(5)/18*(b*gtot_3*6*op_l1_w4*g1_3*(rw**4))/s_eff
                m1_sf = m1_sf + 21*eta_p - iv.log(1-norm_A) - norm_A
            best = iv.mpf("1e9")
            for kr_num in (2, 3, 4, 5, 6, 8, 10, 13):
                rho = (iv.mpf(kr_num)/10)/iv.sqrt(b*s_soft); rc = rw + rho
                if mp.mpf(iv_sinh(rc).b) >= mp.mpf("0.84"): continue
