        def _eval_bkar_flat(b_num: int, wpm: Fraction, v4m: Fraction, use_lou: bool, coord_m: Fraction, tmode: str):
            b = iv.mpf(b_num); s_eff = iv.mpf(1) + iv.mpf(1)/(iv.mpf(6)*b)
