                rho_ch = w_C*(sum_dw + sum_dj)
                rho_tr = w_C*(wpdp*b*(c_l2_sq/((iv.mpf(6)*op_l1_r)**2))*(k_op_r/s_eff)*((iv.mpf(6)*hop_3*rw)**2) + (k_op_r/(iv.mpf(6)*op_l1_r))*sum_dj)
                ev41 = ev56w if use_lou else v4_m*b*iv.sqrt(e_v4_2)/((b*s_eff)**2)
